public class MutableDateTime_add_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testAdd_NullType_ThrowsException() {
        MutableDateTime dateTime = new MutableDateTime();
        dateTime.add(null, 1);
    }

    @Test
    public void testAdd_AmountOne_DoesNothing() {
        // The code has: if (amount != 1) { ... }
        // If amount is 1, the logic is skipped.
        // We verify that the value remains unchanged.
        int year = 2023;
        int month = 1;
        int day = 1;
        MutableDateTime dateTime = new MutableDateTime(year, month, day, 0, 0, 0, 0);
        long originalMillis = dateTime.getMillis();

        dateTime.add(DurationFieldType.year(), 1);

        assertEquals("Value should not change when amount is 1", originalMillis, dateTime.getMillis());
    }

    @Test
    public void testAdd_AmountNotOne_AddsYears() {
        // Test adding years (amount != 1)
        MutableDateTime dateTime = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        dateTime.add(DurationFieldType.year(), 2);

        assertEquals(2025, dateTime.getYear());
        assertEquals(1, dateTime.getMonthOfYear());
        assertEquals(1, dateTime.getDayOfMonth());
    }

    @Test
    public void testAdd_AmountNotOne_AddsMonths() {
        MutableDateTime dateTime = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        dateTime.add(DurationFieldType.monthOfYear(), 3);

        assertEquals(2023, dateTime.getYear());
        assertEquals(4, dateTime.getMonthOfYear());
    }

    @Test
    public void testAdd_AmountNotOne_AddsDays() {
        MutableDateTime dateTime = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        dateTime.add(DurationFieldType.dayOfMonth(), 5);

        assertEquals(6, dateTime.getDayOfMonth());
    }

    @Test
    public void testAdd_AmountNotOne_AddsHours() {
        MutableDateTime dateTime = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        dateTime.add(DurationFieldType.hourOfDay(), 2);

        assertEquals(12, dateTime.getHourOfDay());
    }

    @Test
    public void testAdd_AmountNotOne_NegativeAmount() {
        // Test negative amount to ensure branch coverage for amount != 1
        MutableDateTime dateTime = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        dateTime.add(DurationFieldType.year(), -1);

        assertEquals(2022, dateTime.getYear());
    }

    @Test
    public void testAdd_AmountNotOne_ZeroAmount() {
        // Test amount 0 to ensure branch coverage for amount != 1
        MutableDateTime dateTime = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        long originalMillis = dateTime.getMillis();

        dateTime.add(DurationFieldType.dayOfMonth(), 0);

        assertEquals(originalMillis, dateTime.getMillis());
    }
}
